const extractTitle = (root: Program, varToImport: Record<string, string>) => {
  const result = {
    title: undefined,
    of: undefined,
    name: undefined,
    summary: undefined,
    isTemplate: false,
  } as {
    title: string | undefined;
    of: string | undefined;
    name: string | undefined;
    summary: string | undefined;
    isTemplate: boolean;
