type ImportMap = Record<string, string>;
type ArrayElement = Expression | SpreadElement | null;

const mdxSyntaxOptions = {
  acorn: Parser.extend(acornJsx()),
  acornOptions: { ecmaVersion: 2024 as const, sourceType: 'module' as const },
  addResult: true,
};

